import{_ as a,o as n,c as e,a5 as m}from"./chunks/framework.B5tqjWbr.js";const h=JSON.parse('{"title":"CT-08 根轨迹分析 - 知识检验","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","section":"电机控制","chapter":"control-theory","chapterTitle":"控制理论","chapterOrder":10,"category":"控制理论","source":"motor","visibility":"public","title":"CT-08 根轨迹分析 - 知识检验","tags":["motor-control"],"status":"learning","summary":"**模块：** CT-08 根轨迹分析 **题目数量：** 10道 **难度分布：** ★★★☆☆ 基础题 3道 | ★★★★☆ 进阶题 4道 | ★★★★★ 专业题 3道","navGroup":"控制与算法","navGroupOrder":30},"headers":[],"relativePath":"content/motor/control-theory/CT-08-assessment.md","filePath":"content/motor/control-theory/CT-08-assessment.md","lastUpdated":1783096495000}'),t={name:"content/motor/control-theory/CT-08-assessment.md"};function p(l,s,r,i,o,c){return n(),e("div",null,[...s[0]||(s[0]=[m(`<h1 id="ct-08-根轨迹分析-知识检验" tabindex="-1">CT-08 根轨迹分析 - 知识检验 <a class="header-anchor" href="#ct-08-根轨迹分析-知识检验" aria-label="Permalink to &quot;CT-08 根轨迹分析 - 知识检验&quot;">​</a></h1><p><strong>模块：</strong> CT-08 根轨迹分析 <strong>题目数量：</strong> 10道 <strong>难度分布：</strong> ★★★☆☆ 基础题 3道 | ★★★★☆ 进阶题 4道 | ★★★★★ 专业题 3道</p><hr><h2 id="一、概念判断题-★★★☆☆" tabindex="-1">一、概念判断题（★★★☆☆） <a class="header-anchor" href="#一、概念判断题-★★★☆☆" aria-label="Permalink to &quot;一、概念判断题（★★★☆☆）&quot;">​</a></h2><h3 id="题目1-根轨迹条件判断" tabindex="-1">题目1：根轨迹条件判断 <a class="header-anchor" href="#题目1-根轨迹条件判断" aria-label="Permalink to &quot;题目1：根轨迹条件判断&quot;">​</a></h3><p><strong>问题：</strong> 某电机电流环开环传递函数为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>G</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mfrac><mrow><mi>K</mi></mrow><mrow><mi>s</mi><mo>(</mo><mi>s</mi><mo>+</mo><mn>5</mn><mn>0</mn><mn>0</mn><mo>)</mo><mo>(</mo><mi>s</mi><mo>+</mo><mn>2</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">G(s) = \\frac{K}{s(s+500)(s+2000)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.872331em;"></span><span class="strut bottom" style="height:1.392331em;vertical-align:-0.52em;"></span><span class="base textstyle uncramped"><span class="mord mathit">G</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.34500000000000003em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mclose">)</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mclose">)</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">K</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span>，判断以下各点哪些在根轨迹上：s₁ = -100, s₂ = -250 + j433, s₃ = -1000 + j1000。请说明判断依据。</p><p><strong>参考答案：</strong> 根据相角条件 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">∠</mi><mi>G</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mo>(</mo><mn>2</mn><mi>k</mi><mo>+</mo><mn>1</mn><mo>)</mo><mi>π</mi></mrow><annotation encoding="application/x-tex">\\angle G(s) = (2k+1)\\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">∠</span><span class="mord mathit">G</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathit" style="margin-right:0.03148em;">k</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mord mathit" style="margin-right:0.03588em;">π</span></span></span></span>：</p><ul><li>s₁ = -100：\\angle G = -0° - 0° - 0° = 0° → <strong>不在根轨迹上</strong></li><li>s₂ = -250 + j433：\\angle G = -120° - 60° - 13.7° = -193.7° ≈ -180° → <strong>在根轨迹上</strong></li><li>s₃ = -1000 + j1000：\\angle G = -135° - 63.4° - 45° = -243.4° → <strong>不在根轨迹上</strong></li></ul><hr><h2 id="二、参数计算题-★★★☆☆" tabindex="-1">二、参数计算题（★★★☆☆） <a class="header-anchor" href="#二、参数计算题-★★★☆☆" aria-label="Permalink to &quot;二、参数计算题（★★★☆☆）&quot;">​</a></h2><h3 id="题目2-电流环pi控制的阻尼比计算" tabindex="-1">题目2：电流环PI控制的阻尼比计算 <a class="header-anchor" href="#题目2-电流环pi控制的阻尼比计算" aria-label="Permalink to &quot;题目2：电流环PI控制的阻尼比计算&quot;">​</a></h3><p><strong>问题：</strong> 一台PMSM电流环参数：L = 0.5mH，R = 0.1Ω，PI控制器 Kp = 0.6，Ki = 150。</p><ol><li>计算闭环系统的阻尼比 ζ</li><li>该系统是过阻尼、临界阻尼还是欠阻尼？</li><li>若希望 ζ = 0.707，Kp 应调整为多少？（Ki 保持不变）</li></ol><p><strong>参考答案：</strong></p><ol><li>特征方程：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>0</mn><mn>5</mn><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>1</mn><mo>+</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>6</mn><mo>)</mo><mi>s</mi><mo>+</mo><mn>1</mn><mn>5</mn><mn>0</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">0.0005s^2 + (0.1+0.6)s + 150 = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">5</span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">6</span><span class="mclose">)</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span>，即 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>0</mn><mn>5</mn><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>7</mn><mi>s</mi><mo>+</mo><mn>1</mn><mn>5</mn><mn>0</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">0.0005s^2 + 0.7s + 150 = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">5</span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">7</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> 标准化：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><mn>1</mn><mn>4</mn><mn>0</mn><mn>0</mn><mi>s</mi><mo>+</mo><mn>3</mn><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">s^2 + 1400s + 300000 = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>ω</mi><mi>n</mi></msub><mo>=</mo><msqrt><mrow><mn>3</mn><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn></mrow></msqrt><mo>=</mo><mn>5</mn><mn>4</mn><mn>7</mn><mi mathvariant="normal">.</mi><mn>7</mn></mrow><annotation encoding="application/x-tex">\\omega_n = \\sqrt{300000} = 547.7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.9072200000000001em;"></span><span class="strut bottom" style="height:1.05722em;vertical-align:-0.15em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">n</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="sqrt mord"><span class="sqrt-sign" style="top:-0.06722000000000006em;"><span class="style-wrap reset-textstyle textstyle uncramped">√</span></span><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="mord textstyle cramped"><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span><span style="top:-0.8272200000000001em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped sqrt-line"></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">4</span><span class="mord mathrm">7</span><span class="mord mathrm">.</span><span class="mord mathrm">7</span></span></span></span> rad/s <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mi>ζ</mi><msub><mi>ω</mi><mi>n</mi></msub><mo>=</mo><mn>1</mn><mn>4</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">2\\zeta\\omega_n = 1400</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.8888799999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathit" style="margin-right:0.07378em;">ζ</span><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">n</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span> → <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>ζ</mi><mo>=</mo><mn>1</mn><mn>4</mn><mn>0</mn><mn>0</mn><mi mathvariant="normal">/</mi><mo>(</mo><mn>2</mn><mo>×</mo><mn>5</mn><mn>4</mn><mn>7</mn><mi mathvariant="normal">.</mi><mn>7</mn><mo>)</mo><mo>=</mo><mn>1</mn><mi mathvariant="normal">.</mi><mn>2</mn><mn>7</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">\\zeta = 1400/(2 \\times 547.7) = 1.278</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07378em;">ζ</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">/</span><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mord mathrm">4</span><span class="mord mathrm">7</span><span class="mord mathrm">.</span><span class="mord mathrm">7</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">.</span><span class="mord mathrm">2</span><span class="mord mathrm">7</span><span class="mord mathrm">8</span></span></span></span></li><li>ζ = 1.278 &gt; 1 → <strong>过阻尼</strong>，系统无超调，响应较慢</li><li>ζ = 0.707 → <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>7</mn><mn>0</mn><mn>7</mn><mo>×</mo><mn>5</mn><mn>4</mn><mn>7</mn><mi mathvariant="normal">.</mi><mn>7</mn><mo>=</mo><mn>7</mn><mn>7</mn><mn>4</mn><mi mathvariant="normal">.</mi><mn>6</mn></mrow><annotation encoding="application/x-tex">2 \\times 0.707 \\times 547.7 = 774.6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mord mathrm">4</span><span class="mord mathrm">7</span><span class="mord mathrm">.</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">7</span><span class="mord mathrm">7</span><span class="mord mathrm">4</span><span class="mord mathrm">.</span><span class="mord mathrm">6</span></span></span></span> → 新系数 0.1 + Kp = 0.0005 × 774.6 = 0.387 → <strong>Kp = 0.287</strong></li></ol><hr><h3 id="题目3-根轨迹分离点计算" tabindex="-1">题目3：根轨迹分离点计算 <a class="header-anchor" href="#题目3-根轨迹分离点计算" aria-label="Permalink to &quot;题目3：根轨迹分离点计算&quot;">​</a></h3><p><strong>问题：</strong> 某简化电机速度环开环传递函数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>G</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mfrac><mrow><mi>K</mi></mrow><mrow><mi>s</mi><mo>(</mo><mi>s</mi><mo>+</mo><mn>2</mn><mo>)</mo><mo>(</mo><mi>s</mi><mo>+</mo><mn>5</mn><mo>)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">G(s) = \\frac{K}{s(s+2)(s+5)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.872331em;"></span><span class="strut bottom" style="height:1.392331em;vertical-align:-0.52em;"></span><span class="base textstyle uncramped"><span class="mord mathit">G</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.34500000000000003em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mclose">)</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">K</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span>。</p><ol><li>计算根轨迹在实轴上的分离点</li><li>该分离点对应的增益 K 是多少？</li><li>该分离点在电机控制中的物理意义是什么？</li></ol><p><strong>参考答案：</strong></p><ol><li><p>分离点方程：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><mn>1</mn></mrow><mrow><mi>s</mi></mrow></mfrac><mo>+</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mi>s</mi><mo>+</mo><mn>2</mn></mrow></mfrac><mo>+</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mi>s</mi><mo>+</mo><mn>5</mn></mrow></mfrac><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\frac{1}{s} + \\frac{1}{s+2} + \\frac{1}{s+5} = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.845108em;"></span><span class="strut bottom" style="height:1.2484389999999999em;vertical-align:-0.403331em;"></span><span class="base textstyle uncramped"><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">+</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">+</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">5</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> 即 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><mn>1</mn><mn>4</mn><mi>s</mi><mo>+</mo><mn>1</mn><mn>0</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">3s^2 + 14s + 10 = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> → <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>s</mi><mo>=</mo><mfrac><mrow><mo>−</mo><mn>1</mn><mn>4</mn><mo>±</mo><msqrt><mrow><mn>1</mn><mn>9</mn><mn>6</mn><mo>−</mo><mn>1</mn><mn>2</mn><mn>0</mn></mrow></msqrt></mrow><mrow><mn>6</mn></mrow></mfrac><mo>=</mo><mfrac><mrow><mo>−</mo><mn>1</mn><mn>4</mn><mo>±</mo><mn>8</mn><mi mathvariant="normal">.</mi><mn>7</mn><mn>1</mn><mn>8</mn></mrow><mrow><mn>6</mn></mrow></mfrac></mrow><annotation encoding="application/x-tex">s = \\frac{-14 \\pm \\sqrt{196 - 120}}{6} = \\frac{-14 \\pm 8.718}{6}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.05em;"></span><span class="strut bottom" style="height:1.395em;vertical-align:-0.345em;"></span><span class="base textstyle uncramped"><span class="mord mathit">s</span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">6</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.41861149999999997em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord">−</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mbin">±</span><span class="sqrt mord"><span class="sqrt-sign" style="top:-0.044840714285714234em;"><span class="style-wrap reset-scriptstyle scriptstyle uncramped">√</span></span><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1.4285714285714286em;">​</span></span><span class="mord scriptstyle cramped"><span class="mord mathrm">1</span><span class="mord mathrm">9</span><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span><span style="top:-0.7876978571428571em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1.4285714285714286em;">​</span></span><span class="reset-scriptstyle textstyle uncramped sqrt-line"></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1.4285714285714286em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">6</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord">−</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mbin">±</span><span class="mord mathrm">8</span><span class="mord mathrm">.</span><span class="mord mathrm">7</span><span class="mord mathrm">1</span><span class="mord mathrm">8</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></p><p>s₁ = -0.880（在根轨迹区段 [0, -2] 上）→ <strong>分离点</strong> s₂ = -3.787（在 [-2, -5] 区间，是会合点）</p></li><li><p>幅值条件：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>K</mi><mo>=</mo><mi mathvariant="normal">∣</mi><mi>s</mi><mi mathvariant="normal">∣</mi><mo>⋅</mo><mi mathvariant="normal">∣</mi><mi>s</mi><mo>+</mo><mn>2</mn><mi mathvariant="normal">∣</mi><mo>⋅</mo><mi mathvariant="normal">∣</mi><mi>s</mi><mo>+</mo><mn>5</mn><mi mathvariant="normal">∣</mi></mrow><annotation encoding="application/x-tex">K = |s| \\cdot |s+2| \\cdot |s+5|</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mrel">=</span><span class="mord mathrm">∣</span><span class="mord mathit">s</span><span class="mord mathrm">∣</span><span class="mbin">⋅</span><span class="mord mathrm">∣</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">∣</span><span class="mbin">⋅</span><span class="mord mathrm">∣</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mord mathrm">∣</span></span></span></span> s₁ = -0.880: K = 0.880 × 1.12 × 4.12 = <strong>4.06</strong></p></li><li><p>物理意义：当速度环增益 K &lt; 4.06 时，系统为过阻尼（三个实极点）；K = 4.06 时临界阻尼；K &gt; 4.06 时出现一对共轭极点→速度响应出现振荡。<strong>这就是为什么速度环增益设置过大会导致电机啸叫。</strong></p></li></ol><hr><h2 id="三、分析设计题-★★★★☆" tabindex="-1">三、分析设计题（★★★★☆） <a class="header-anchor" href="#三、分析设计题-★★★★☆" aria-label="Permalink to &quot;三、分析设计题（★★★★☆）&quot;">​</a></h2><h3 id="题目4-根轨迹与bode图的对应关系" tabindex="-1">题目4：根轨迹与Bode图的对应关系 <a class="header-anchor" href="#题目4-根轨迹与bode图的对应关系" aria-label="Permalink to &quot;题目4：根轨迹与Bode图的对应关系&quot;">​</a></h3><p><strong>问题：</strong> 对电流环 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>G</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mfrac><mrow><msub><mi>K</mi><mi>p</mi></msub><mi>s</mi><mo>+</mo><msub><mi>K</mi><mi>i</mi></msub></mrow><mrow><mi>s</mi><mo>(</mo><mi>L</mi><mi>s</mi><mo>+</mo><mi>R</mi><mo>)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">G(s) = \\frac{K_p s + K_i}{s(Ls + R)}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.990551em;"></span><span class="strut bottom" style="height:1.510551em;vertical-align:-0.52em;"></span><span class="base textstyle uncramped"><span class="mord mathit">G</span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.34500000000000003em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mopen">(</span><span class="mord mathit">L</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.00773em;">R</span><span class="mclose">)</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.51222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15000000000000002em;margin-right:0.07142857142857144em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">p</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">i</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span>，L=0.8mH, R=0.15Ω, Ki=120。</p><ol><li>画出 Kp 从 0.1 到 2.0 的根轨迹草图，标注分离点和 ζ=0.707 点</li><li>分别用根轨迹法和Bode图法解释：为什么 Kp 过大会导致振荡？</li><li>这两种分析方法给出的结论是否一致？如果不一致，原因是什么？</li></ol><p><strong>参考答案：</strong></p><ol><li><p>（略，要求学生在草图上标注开环极点 (0, 0) 和 (-187.5, 0)，开环零点 = -Ki/Kp 随 Kp 变化，分离点计算...）</p></li><li><p><strong>根轨迹法：</strong> Kp 增大→共轭极点虚部增大→阻尼比 ζ 减小→超调增大→振荡 <strong>Bode图法：</strong> Kp 增大→剪切频率升高→相位裕度减小→当相位裕度&lt;0时系统不稳定</p></li><li><p>两种方法在二阶系统中结论一致。但对于高阶系统（如考虑数字延迟的速度环），Bode图可能显示出更保守的稳定条件（因为Bode图考虑的是频率响应而非极点位置）。<strong>在电机控制中，通常先根轨迹设计极点位置，再用Bode图验证相位裕度。</strong></p></li></ol><hr><h3 id="题目5-速度环根轨迹与临界增益" tabindex="-1">题目5：速度环根轨迹与临界增益 <a class="header-anchor" href="#题目5-速度环根轨迹与临界增益" aria-label="Permalink to &quot;题目5：速度环根轨迹与临界增益&quot;">​</a></h3><p><strong>问题：</strong> 一台永磁同步电机的速度环开环传递函数为：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>G</mi><mrow><mi>o</mi><mi>l</mi></mrow></msub><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mfrac><mrow><mi>K</mi><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>5</mn><mi>s</mi><mo>+</mo><mn>1</mn><mo>)</mo></mrow><mrow><mi>s</mi><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>1</mn><mi>s</mi><mo>+</mo><mn>1</mn><mo>)</mo><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>1</mn><mi>s</mi><mo>+</mo><mn>1</mn><mo>)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">G_{ol}(s) = \\frac{K(0.05s + 1)}{s(0.001s + 1)(0.01s + 1)} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.427em;"></span><span class="strut bottom" style="height:2.363em;vertical-align:-0.936em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">o</span><span class="mord mathit" style="margin-right:0.01968em;">l</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathit">s</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span><span style="top:-0.2300000000000001em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">5</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></span></p><p>其中 K = Ksp·Kt/J，是速度环总增益。</p><ol><li>计算系统稳定的 K 值范围（用Routh判据）</li><li>当 K = K_critical 时，振荡频率是多少？</li><li>在电机速度环调试中，如何利用这一信息避免振荡？</li></ol><p><strong>参考答案：</strong></p><ol><li><p>特征方程：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>s</mi><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>1</mn><mi>s</mi><mo>+</mo><mn>1</mn><mo>)</mo><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>1</mn><mi>s</mi><mo>+</mo><mn>1</mn><mo>)</mo><mo>+</mo><mi>K</mi><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>5</mn><mi>s</mi><mo>+</mo><mn>1</mn><mo>)</mo><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">s(0.001s+1)(0.01s+1) + K(0.05s+1) = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit">s</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">5</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> 展开：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>5</mn></mrow></msup><msup><mi>s</mi><mn>3</mn></msup><mo>+</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>1</mn><mn>1</mn><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><mo>(</mo><mn>1</mn><mo>+</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>5</mn><mi>K</mi><mo>)</mo><mi>s</mi><mo>+</mo><mi>K</mi><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">10^{-5}s^3 + 0.011s^2 + (1+0.05K)s + K = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord"><span class="mord mathrm">0</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord">−</span><span class="mord mathrm">5</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">3</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">5</span><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mclose">)</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> Routh表：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s³ | 10⁻⁵         1+0.05K</span></span>
<span class="line"><span>s² | 0.011        K</span></span>
<span class="line"><span>s¹ | (0.011(1+0.05K)-10⁻⁵K)/0.011 = (0.011+0.00055K-10⁻⁵K)/0.011</span></span>
<span class="line"><span>s⁰ | K</span></span></code></pre></div><p>第一列全正 → <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>1</mn><mn>1</mn><mo>+</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>0</mn><mn>5</mn><mn>4</mn><mi>K</mi><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">0.011 + 0.00054K &gt; 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">5</span><span class="mord mathrm">4</span><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mrel">&gt;</span><span class="mord mathrm">0</span></span></span></span> 且 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>K</mi><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">K &gt; 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.72243em;vertical-align:-0.0391em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mrel">&gt;</span><span class="mord mathrm">0</span></span></span></span> → <strong>K &lt; 20.37</strong>（0.011/0.00054 ≈ 20.37）</p></li><li><p>临界时 s¹ 行=0，辅助方程 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>1</mn><mn>1</mn><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><mn>2</mn><mn>0</mn><mi mathvariant="normal">.</mi><mn>3</mn><mn>7</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">0.011s^2 + 20.37 = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> → <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>s</mi><mo>=</mo><mo>±</mo><mi>j</mi><msqrt><mrow><mn>2</mn><mn>0</mn><mi mathvariant="normal">.</mi><mn>3</mn><mn>7</mn><mi mathvariant="normal">/</mi><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>1</mn><mn>1</mn></mrow></msqrt><mo>=</mo><mo>±</mo><mi>j</mi><mn>4</mn><mn>3</mn><mi mathvariant="normal">.</mi><mn>0</mn></mrow><annotation encoding="application/x-tex">s = \\pm j\\sqrt{20.37/0.011} = \\pm j43.0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.9350050000000001em;"></span><span class="strut bottom" style="height:1.24001em;vertical-align:-0.3050049999999999em;"></span><span class="base textstyle uncramped"><span class="mord mathit">s</span><span class="mrel">=</span><span class="mord">±</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="sqrt mord"><span class="sqrt-sign" style="top:-0.04500500000000007em;"><span class="style-wrap reset-textstyle textstyle uncramped"><span class="delimsizing size1">√</span></span></span><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="mord textstyle cramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mord mathrm">/</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span></span></span><span style="top:-0.855005em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped sqrt-line"></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord">±</span><span class="mord mathit" style="margin-right:0.05724em;">j</span><span class="mord mathrm">4</span><span class="mord mathrm">3</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span></span></span></span> rad/s → 振荡频率 f = 43.0/(2π) = <strong>6.85 Hz</strong></p></li><li><p>调试策略：</p><ul><li>逐步增大 Ksp，同时监测速度反馈信号</li><li>当检测到约 7Hz 的速度振荡时，说明已接近临界增益</li><li>将 Ksp 回调至 0.5×K_critical 以获得足够稳定裕度</li><li><strong>实际经验：速度环振荡频率通常在 5~30 Hz 范围，可用频谱分析仪确认</strong></li></ul></li></ol><hr><h3 id="题目6-电流环pi参数的根轨迹法整定" tabindex="-1">题目6：电流环PI参数的根轨迹法整定 <a class="header-anchor" href="#题目6-电流环pi参数的根轨迹法整定" aria-label="Permalink to &quot;题目6：电流环PI参数的根轨迹法整定&quot;">​</a></h3><p><strong>问题：</strong> 已知 PMSM 参数 L = 1.2mH, R = 0.25Ω, 期望电流环阻尼比 ζ = 0.707，调节时间 ts ≤ 5ms。</p><ol><li>分别计算 Kp 和 Ki（假设采用零极点对消法）</li><li>如果不采用对消法，用根轨迹法在复平面上选择满足要求的极点位置，给出对应的 Kp, Ki</li><li>比较两种方法得到的PI参数，分析各自的优缺点</li></ol><p><strong>参考答案：</strong></p><ol><li><p><strong>零极点对消：</strong> Ki/Kp = R/L = 0.25/0.0012 = 208.33 ts = 4/(ζωn) ≤ 5ms → ωn ≥ 4/(0.707 × 0.005) = 1132 rad/s Kp = L·ωc = 0.0012 × 1132 = 1.36, Ki = Kp × 208.33 = 283</p></li><li><p><strong>根轨迹法：</strong> 特征方程 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>1</mn><mn>2</mn><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><mo>(</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>2</mn><mn>5</mn><mo>+</mo><msub><mi>K</mi><mi>p</mi></msub><mo>)</mo><mi>s</mi><mo>+</mo><msub><mi>K</mi><mi>i</mi></msub><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">0.0012s^2 + (0.25+K_p)s + K_i = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.1002159999999999em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">p</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mclose">)</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">i</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> 要求 ζ = 0.707, σ ≥ 800 (ts ≤ 5ms) 极点位于 s = -σ ± jσ (45°线) 代入特征方程匹配实部虚部： 实部：0.0012(-2σ²) + (0.25+K_p)(-σ) + K_i = 0 虚部：2×0.0012×σ² = 0（矛盾，二阶系统ζ=0.707时虚部不为零） 正确解法：(s - s₁)(s - s₂) = s^2 + 2ζω_n s + ω_n² = 0 其中 s² + (0.25+K_p)/0.0012·s + K_i/0.0012 = 0 匹配：2ζω_n = (0.25+K_p)/0.0012, ω_n² = K_i/0.0012 选 ωn = 1132, ζ = 0.707 → Kp = 2ζωn·L - R = 2×0.707×1132×0.0012 - 0.25 = 1.67 Ki = ωn²·L = 1132² × 0.0012 = 1538</p></li><li><p><strong>比较：</strong></p><ul><li>对消法：Kp=1.36, Ki=283 → 带宽低，保守，适合参数准确的情况</li><li>根轨迹法：Kp=1.67, Ki=1538 → Ki 远大于对消法，响应更快但可能引起积分饱和</li><li><strong>工程建议：</strong> 先用根轨迹法确定理论最优值，实际调试时 Ki 适当折衷（取理论值的 50~70%）避免积分饱和，然后用对消法的 Kp/Ki 比例关系作为下限约束。</li></ul></li></ol><hr><h3 id="题目7-数字延迟对根轨迹的影响" tabindex="-1">题目7：数字延迟对根轨迹的影响 <a class="header-anchor" href="#题目7-数字延迟对根轨迹的影响" aria-label="Permalink to &quot;题目7：数字延迟对根轨迹的影响&quot;">​</a></h3><p><strong>问题：</strong> 电机FOC控制中，电流采样到PWM更新存在一拍延迟 Td = 1/fs（fs为PWM频率）。该延迟近似为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msup><mi>e</mi><mrow><mo>−</mo><msub><mi>T</mi><mi>d</mi></msub><mi>s</mi></mrow></msup><mo>≈</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>T</mi><mi>d</mi></msub><mi>s</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">e^{-T_d s} \\approx \\frac{1}{1+T_d s}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.845108em;"></span><span class="strut bottom" style="height:1.2959679999999998em;vertical-align:-0.4508599999999999em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">e</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord">−</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">d</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">≈</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">d</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span>。</p><ol><li>写出考虑延迟的电流环开环传递函数</li><li>分析延迟对根轨迹的影响（fs = 10kHz vs 20kHz）</li><li>给出考虑延迟时的最大允许 Kp</li></ol><p><strong>参考答案：</strong></p><ol><li><p><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>G</mi><mrow><mi>o</mi><mi>l</mi></mrow></msub><mo>(</mo><mi>s</mi><mo>)</mo><mo>=</mo><mfrac><mrow><msub><mi>K</mi><mi>p</mi></msub><mi>s</mi><mo>+</mo><msub><mi>K</mi><mi>i</mi></msub></mrow><mrow><mi>s</mi></mrow></mfrac><mo>⋅</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mi>L</mi><mi>s</mi><mo>+</mo><mi>R</mi></mrow></mfrac><mo>⋅</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>T</mi><mi>d</mi></msub><mi>s</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">G_{ol}(s) = \\frac{K_p s + K_i}{s} \\cdot \\frac{1}{Ls+R} \\cdot \\frac{1}{1+T_d s}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.990551em;"></span><span class="strut bottom" style="height:1.441411em;vertical-align:-0.4508599999999999em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">G</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">o</span><span class="mord mathit" style="margin-right:0.01968em;">l</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit">s</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.51222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15000000000000002em;margin-right:0.07142857142857144em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">p</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.07142857142857144em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">i</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">⋅</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">L</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.00773em;">R</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">⋅</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">d</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">s</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></p></li><li><p>延迟引入了一个额外的极点 s = -1/Td：</p><ul><li>fs = 10kHz: Td = 0.1ms, 极点 s = -10000</li><li>fs = 20kHz: Td = 0.05ms, 极点 s = -20000</li></ul><p>该额外极点使根轨迹在右偏转——原本稳定的高增益在引入延迟后可能不稳定。fs越低，额外极点越靠近虚轴，对稳定性的影响越大。</p></li><li><p>特征方程变为三阶： <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>T</mi><mi>d</mi></msub><mi>L</mi><msup><mi>s</mi><mn>3</mn></msup><mo>+</mo><mo>(</mo><mi>L</mi><mo>+</mo><msub><mi>T</mi><mi>d</mi></msub><mi>R</mi><mo>)</mo><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><mo>(</mo><mi>R</mi><mo>+</mo><msub><mi>K</mi><mi>p</mi></msub><mo>)</mo><mi>s</mi><mo>+</mo><msub><mi>K</mi><mi>i</mi></msub><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">T_d L s^3 + (L + T_d R)s^2 + (R + K_p)s + K_i = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.1002159999999999em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">d</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit">L</span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">3</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathit">L</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">d</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathit" style="margin-right:0.00773em;">R</span><span class="mclose">)</span><span class="mord"><span class="mord mathit">s</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.00773em;">R</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">p</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mclose">)</span><span class="mord mathit">s</span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">i</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span></p><p>用Routh判据：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>K</mi><mi>p</mi></msub><mo>&lt;</mo><mfrac><mrow><mi>L</mi></mrow><mrow><msub><mi>T</mi><mi>d</mi></msub></mrow></mfrac></mrow><annotation encoding="application/x-tex">K_p &lt; \\frac{L}{T_d}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.872331em;"></span><span class="strut bottom" style="height:1.323191em;vertical-align:-0.4508599999999999em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">p</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">&lt;</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15122857142857138em;margin-right:0.07142857142857144em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-scriptstyle scriptscriptstyle cramped"><span class="mord mathit">d</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathit">L</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span> （近似，忽略小项） fs=10kHz: <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>K</mi><mi>p</mi></msub><mo>&lt;</mo><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>1</mn><mn>2</mn><mi mathvariant="normal">/</mi><mn>0</mn><mi mathvariant="normal">.</mi><mn>0</mn><mn>0</mn><mn>0</mn><mn>1</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">K_p &lt; 0.0012/0.0001 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1.036108em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">p</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">&lt;</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">/</span><span class="mord mathrm">0</span><span class="mord mathrm">.</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span> → 安全范围很大，<strong>正常PI参数(0.5~2.0)不会受延迟影响</strong> 但当 Kp 极高（如无差拍控制）时，延迟必须考虑</p></li></ol><hr><h2 id="四、综合应用题-★★★★☆" tabindex="-1">四、综合应用题（★★★★☆） <a class="header-anchor" href="#四、综合应用题-★★★★☆" aria-label="Permalink to &quot;四、综合应用题（★★★★☆）&quot;">​</a></h2><h3 id="题目8-级联控制的根轨迹设计" tabindex="-1">题目8：级联控制的根轨迹设计 <a class="header-anchor" href="#题目8-级联控制的根轨迹设计" aria-label="Permalink to &quot;题目8：级联控制的根轨迹设计&quot;">​</a></h3><p><strong>问题：</strong> 典型的电机三环级联控制中，内环（电流环）带宽通常是外环（速度环）的5~10倍。请用根轨迹方法解释：</p><ol><li>为什么电流环带宽必须远大于速度环带宽？</li><li>如果电流环带宽仅3倍于速度环，根轨迹会如何变化？</li><li>给出基于根轨迹的电流环-速度环带宽比设计准则</li></ol><p><strong>参考答案：</strong></p><ol><li><p>速度环设计时，电流环被近似为一阶惯性环节 1/(τ_c s + 1)。只有当电流环极点 τ_c 远小于速度环主导极点时，这一近似才成立。根轨迹上表现为：电流环极点远离速度环区域，不发生交互。</p></li><li><p>带宽比仅3倍 → 电流环极点与速度环极点接近 → 根轨迹上两条支路互相&quot;排斥&quot; → 原本的共轭极点对阻尼减小 → 速度环超调增大，甚至不稳定。</p></li><li><p><strong>设计准则：</strong></p><ul><li>带宽比 ≥ 5: 电流环极点与速度环极点完全解耦，速度环设计可忽略电流环动态</li><li>带宽比 3~5: 需将电流环极点纳入速度环根轨迹分析，适当降低速度环增益</li><li>带宽比 &lt; 3: 不可接受，必须提高电流环带宽或降低速度环带宽</li></ul></li></ol><hr><h2 id="五、前沿综合题-★★★★★" tabindex="-1">五、前沿综合题（★★★★★） <a class="header-anchor" href="#五、前沿综合题-★★★★★" aria-label="Permalink to &quot;五、前沿综合题（★★★★★）&quot;">​</a></h2><h3 id="题目9-参数不确定性下的根轨迹鲁棒设计" tabindex="-1">题目9：参数不确定性下的根轨迹鲁棒设计 <a class="header-anchor" href="#题目9-参数不确定性下的根轨迹鲁棒设计" aria-label="Permalink to &quot;题目9：参数不确定性下的根轨迹鲁棒设计&quot;">​</a></h3><p><strong>问题：</strong> 电机运行中，电感 L 因磁饱和可能变化 ±30%，电阻 R 因温升可能变化 +50%。电流环采用PI控制。</p><ol><li>画出 L 和 R 在不确定范围内的根轨迹族（示意即可）</li><li>设计 Kp, Ki 使得在所有参数组合下，闭环极点ζ≥0.5 且 ts≤10ms</li><li>讨论：追求鲁棒性的代价是什么？</li></ol><p><strong>参考答案：</strong></p><ol><li><p>L变化主要影响 ωn（极点离原点距离），R变化主要影响阻尼（极点向实轴靠拢或远离）。L_min + R_max 是最差工况（阻尼最小）。</p></li><li><p>按最差工况设计（L=0.7×L_nom, R=1.5×R_nom）： ζ_min ≥ 0.5 且 σ_min = ζωn ≥ 400 解得：Kp ≥ 2ζωn·L_min - R_max 正常工况下（L_nom, R_nom）：ζ 会偏大，响应偏保守。</p></li><li><p><strong>代价：</strong> 鲁棒设计以最差工况为准，正常工况下性能不是最优（响应偏慢、带宽偏低）。这是性能与鲁棒性的经典trade-off。</p></li></ol><hr><h3 id="题目10-基于根轨迹的电流环自适应增益调度设计" tabindex="-1">题目10：基于根轨迹的电流环自适应增益调度设计 <a class="header-anchor" href="#题目10-基于根轨迹的电流环自适应增益调度设计" aria-label="Permalink to &quot;题目10：基于根轨迹的电流环自适应增益调度设计&quot;">​</a></h3><p><strong>问题：</strong> 设计一个基于根轨迹的自适应PI参数更新方案：</p><ol><li>假设在线辨识出当前电机参数 L_est, R_est，写出PI参数的自适应更新公式（使闭环极点保持在ζ=0.707, ωn=1500）</li><li>画出自适应PI的软件实现流程图（伪代码级）</li><li>讨论：在什么工况下这种自适应最有价值？什么工况下不必要？</li></ol><p><strong>参考答案：</strong></p><ol><li><p>更新公式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kp = 2 × 0.707 × 1500 × L_est - R_est</span></span>
<span class="line"><span>Ki = 1500² × L_est</span></span></code></pre></div></li><li><p>伪代码：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if parameter_update_flag:</span></span>
<span class="line"><span>    L_est = rls_identify_L()</span></span>
<span class="line"><span>    R_est = rls_identify_R()</span></span>
<span class="line"><span>    if L_est &gt; 0.5*L_nom &amp;&amp; L_est &lt; 2.0*L_nom:  // 合理性检查</span></span>
<span class="line"><span>        Kp_new = 2*0.707*1500*L_est - R_est</span></span>
<span class="line"><span>        Ki_new = 1500² * L_est</span></span>
<span class="line"><span>        apply_lowpass_filter(Kp, Kp_new, 0.95)  // 平滑过渡</span></span>
<span class="line"><span>        apply_lowpass_filter(Ki, Ki_new, 0.95)</span></span></code></pre></div></li><li><p><strong>最有价值的工况：</strong></p><ul><li>宽调速范围（弱磁区电感显著变化）</li><li>大负载变化（温度导致R大幅偏移）</li><li>高动态伺服（需要始终保持最优响应）</li></ul><p><strong>不必要的工况：</strong></p><ul><li>恒速恒载运行（参数基本不变）</li><li>对动态响应要求不高的风机泵类负载</li><li>参数辨识精度不足以支持自适应（辨识噪声&gt;参数变化）</li></ul></li></ol>`,68)])])}const y=a(t,[["render",p]]);export{h as __pageData,y as default};
